(3938097, 558656, 60862, '<td valign="top">Very pretty shot, but I''m not getting a particular emotion.</td>', 'Very pretty shot, but I''m not getting a particular emotion.', '2007-07-26 00:10:12.000000', NULL, 1),
(3938106, 560248, 60862, '<td valign="top">The idea is sound, and although others may ding you for showing her face, I think you succeeded in not making her face the main focus.  The shot''s very dim, which complements the emotion and feel of the scene.  But the low contrast just makes it hard to make out the details.  Also, your title is a little too, well, emotionless.  Instead of focusing on the pills, something like "Despair" or "Never Wake Up" would''ve captured the mood better.</td>', 'The idea is sound, and although others may ding you for showing her face, I think you succeeded in not making her face the main focus.  The shot''s very dim, which complements the emotion and feel of the scene.  But the low contrast just makes it hard to make out the details.  Also, your title is a little too, well, emotionless.  Instead of focusing on the pills, something like "Despair" or "Never Wake Up" would''ve captured the mood better.', '2007-07-26 00:12:27.000000', NULL, 1),
(3938109, 560221, 60862, '<td valign="top">Passion for drumming, meaning a strong interest in it, isn''t the same thing as an emotion.  Interesting angle, though.</td>', 'Passion for drumming, meaning a strong interest in it, isn''t the same thing as an emotion.  Interesting angle, though.', '2007-07-26 00:13:37.000000', NULL, 1),
(3938111, 560257, 60862, '<td valign="top">I''m not getting what emotion she''s feeling.  Her being a bride would imply joy, but her standing alone at a window implies despair or loneliness.  Other clues would have made it clearer.</td>', 'I''m not getting what emotion she''s feeling.  Her being a bride would imply joy, but her standing alone at a window implies despair or loneliness.  Other clues would have made it clearer.', '2007-07-26 00:14:27.000000', NULL, 1),
(3938118, 560104, 60862, '<td valign="top">Is that a stuffed penguin?  If so, then the idea works for me.  But the image doesn''t.  On my calibrated CRT monitor, there''s no detail in the penguin, so it''s just a plain black shape.  I thought it was a hedge until I read the title.</td>', 'Is that a stuffed penguin?  If so, then the idea works for me.  But the image doesn''t.  On my calibrated CRT monitor, there''s no detail in the penguin, so it''s just a plain black shape.  I thought it was a hedge until I read the title.', '2007-07-26 00:15:24.000000', NULL, 1),
(3938120, 560552, 60862, '<td valign="top">Ha!  Thanks for the laugh.  Great idea, well posed and well lit.  Nice timing on the clothes, too - how many takes did that require?</td>', 'Ha!  Thanks for the laugh.  Great idea, well posed and well lit.  Nice timing on the clothes, too - how many takes did that require?', '2007-07-26 00:16:07.000000', NULL, 1),
(3938122, 558598, 60862, '<td valign="top">And the emotion is, what?  Since the woman on the right is showing her emotions through her face, and I can''t get anything from the woman on the right''s body language, this shot doesn''t meet the challenge for me.</td>', 'And the emotion is, what?  Since the woman on the right is showing her emotions through her face, and I can''t get anything from the woman on the right''s body language, this shot doesn''t meet the challenge for me.', '2007-07-26 00:17:02.000000', NULL, 1),
(3938125, 559475, 60862, '<td valign="top">All of the driver''s emotion is showing in his face, so this doesn''t meet the challenge.  Fun pic otherwise, though, kind of like  a puzzle to figure out.</td>', 'All of the driver''s emotion is showing in his face, so this doesn''t meet the challenge.  Fun pic otherwise, though, kind of like  a puzzle to figure out.', '2007-07-26 00:17:39.000000', NULL, 1),
(3938132, 560538, 60862, '<td valign="top">Nice use of a color you could isolate.  Clearly shows an extreme emotion, too.</td>', 'Nice use of a color you could isolate.  Clearly shows an extreme emotion, too.', '2007-07-26 00:19:51.000000', NULL, 1),
(3938134, 560200, 60862, '<td valign="top">Very powerfully done.  I really like the grain, too - it adds a lot of punch.</td>', 'Very powerfully done.  I really like the grain, too - it adds a lot of punch.', '2007-07-26 00:20:18.000000', NULL, 1),
(3938136, 559814, 60862, '<td valign="top">Nice composition, well lit, and solid idea.</td>', 'Nice composition, well lit, and solid idea.', '2007-07-26 00:20:37.000000', NULL, 1),
(3938139, 559172, 60862, '<td valign="top">Now this just made me smile, and the title is perfect.  I''m a sucker for pure black silhouettes, too.</td>', 'Now this just made me smile, and the title is perfect.  I''m a sucker for pure black silhouettes, too.', '2007-07-26 00:21:05.000000', NULL, 1),
(3938149, 560340, 56828, '<td valign="top">The light on the left completely takes away from the photo. Should have cropped that out.</td>', 'The light on the left completely takes away from the photo. Should have cropped that out.', '2007-07-26 00:23:52.000000', NULL, 1),
(3938153, 560426, 56539, '<td valign="top">Make sure both his hands are not on your shoulders!</td>', 'Make sure both his hands are not on your shoulders!', '2007-07-26 00:25:23.000000', NULL, 1),
(3938154, 560377, 60862, '<td valign="top">An interesting study,a nd I like the B&amp;W tones.  But I don''t see any emotion, and the main subject is his face, so you''re doubly not meeting the challenge.</td>', 'An interesting study,a nd I like the B&W tones.  But I don''t see any emotion, and the main subject is his face, so you''re doubly not meeting the challenge.', '2007-07-26 00:25:28.000000', NULL, 1),
(3938157, 558302, 60862, '<td valign="top">Heh.  Good idea!</td>', 'Heh.  Good idea!', '2007-07-26 00:26:14.000000', NULL, 1),
(3938160, 560543, 60862, '<td valign="top">Laugh.  I like it!</td>', 'Laugh.  I like it!', '2007-07-26 00:26:29.000000', NULL, 1),
(3938162, 557325, 60862, '<td valign="top">Very harsh lighting, which fits the theme well.</td>', 'Very harsh lighting, which fits the theme well.', '2007-07-26 00:26:45.000000', NULL, 1),
(3938167, 560550, 60862, '<td valign="top">The problem here is that you seem to have assumed the viewer would feel whatever the women are feeling.  But they''re not really showing any emotion, so for me it fails to meet the challenge.<br/> <br/>Outside the challenge, I''d suggest bumping up the contrast a bit - with a little more detail and tonal range in the water, it''d be a really nice shot.</td>', 'The problem here is that you seem to have assumed the viewer would feel whatever the women are feeling.  But they''re not really showing any emotion, so for me it fails to meet the challenge. Outside the challenge, I''d suggest bumping up the contrast a bit - with a little more detail and tonal range in the water, it''d be a really nice shot.', '2007-07-26 00:28:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3938168, 560409, 60862, '<td valign="top">Very nice idea!  I like the B&amp;W tones and composition, too.</td>', 'Very nice idea!  I like the B&W tones and composition, too.', '2007-07-26 00:28:33.000000', NULL, 1),
