(3943938, 559960, 65107, '<td valign="top">I like the colors, but I don''t believe the story, like a B horror flic.</td>', 'I like the colors, but I don''t believe the story, like a B horror flic.', '2007-07-27 23:07:21.000000', NULL, 1),
(3943941, 560324, 65107, '<td valign="top">pretty but mellow emotion</td>', 'pretty but mellow emotion', '2007-07-27 23:08:14.000000', NULL, 1),
