(3947877, 560277, 62249, '<td valign="top">Interesting photo but relies too much on his face for a "faceless" challenge.</td>', 'Interesting photo but relies too much on his face for a "faceless" challenge.', '2007-07-30 00:56:02.000000', NULL, 1),
(3947915, 560222, 62249, '<td valign="top">Nice photo. Greate detail in feathers. Good use of DOF. Doesn''t meet challenge very well, though, since it isn''t a faceless shot.</td>', 'Nice photo. Greate detail in feathers. Good use of DOF. Doesn''t meet challenge very well, though, since it isn''t a faceless shot.', '2007-07-30 01:06:02.000000', NULL, 1),
