(3951861, 559751, 57032, '<td valign="top">The flower looks a bit odd around the edges. Good sharpness. A bit too much contrast in places, but still a great shot!</td>', 'The flower looks a bit odd around the edges. Good sharpness. A bit too much contrast in places, but still a great shot!', '2007-07-31 00:08:51.000000', NULL, 1),
(3951863, 560284, 57032, '<td valign="top">Excellent timing. Good composition and sharpness.</td>', 'Excellent timing. Good composition and sharpness.', '2007-07-31 00:09:06.000000', NULL, 1),
(3951869, 558764, 57032, '<td valign="top">Excellent freeze, and the sharpness of the car is perfect. Exposure is spot-on. I''d guess it''s Skip''s work.</td>', 'Excellent freeze, and the sharpness of the car is perfect. Exposure is spot-on. I''d guess it''s Skip''s work.', '2007-07-31 00:11:02.000000', NULL, 1),
(3951870, 560366, 57032, '<td valign="top">Great capture of mood. Nice lighting.</td>', 'Great capture of mood. Nice lighting.', '2007-07-31 00:11:19.000000', NULL, 1),
