(3951877, 560552, 57032, '<td valign="top">The mood is well captured. Good colour and clarity throughout.</td>', 'The mood is well captured. Good colour and clarity throughout.', '2007-07-31 00:13:05.000000', NULL, 1),
(3951880, 560366, 77724, '<td valign="top">True spirit of this challenge IMHO.  Very well done.</td>', 'True spirit of this challenge IMHO.  Very well done.', '2007-07-31 00:13:42.000000', NULL, 1),
(3951882, 560221, 57032, '<td valign="top">The mood is captured well here. Good sharpness and effective blur.</td>', 'The mood is captured well here. Good sharpness and effective blur.', '2007-07-31 00:13:56.000000', NULL, 1),
(3951891, 560321, 57032, '<td valign="top">Good exposure of the image and sharpened nicely. The background is distracting, particularly above the woman''s hand. I don''t exactly find it to be a lover''s embrace, but a good shot overall.</td>', 'Good exposure of the image and sharpened nicely. The background is distracting, particularly above the woman''s hand. I don''t exactly find it to be a lover''s embrace, but a good shot overall.', '2007-07-31 00:16:31.000000', NULL, 1),
