(3951902, 559731, 57032, '<td valign="top">Good silhouette, nice composition, and great angle! Too bad about the blown highlights in the sky, but an excellent image overall.</td>', 'Good silhouette, nice composition, and great angle! Too bad about the blown highlights in the sky, but an excellent image overall.', '2007-07-31 00:21:15.000000', NULL, 1),
(3951905, 560328, 57032, '<td valign="top">Good angle. Seems out of place against the white background.</td>', 'Good angle. Seems out of place against the white background.', '2007-07-31 00:22:44.000000', NULL, 1),
(3951907, 559018, 57032, '<td valign="top">Good portrayal of emotion. A pretty good B&amp;W.</td>', 'Good portrayal of emotion. A pretty good B&W.', '2007-07-31 00:23:13.000000', NULL, 1),
(3951932, 558074, 57032, '<td valign="top">Good lighting to convey the emotion.</td>', 'Good lighting to convey the emotion.', '2007-07-31 00:36:11.000000', NULL, 1),
