(3951950, 560400, 57032, '<td valign="top">Good lighting and contrast.</td>', 'Good lighting and contrast.', '2007-07-31 00:43:40.000000', NULL, 1),
(3951953, 559890, 57032, '<td valign="top">Excellent focus. Good background and colour throughout.</td>', 'Excellent focus. Good background and colour throughout.', '2007-07-31 00:44:06.000000', NULL, 1),
(3951957, 560361, 57032, '<td valign="top">Good lighting.</td>', 'Good lighting.', '2007-07-31 00:44:56.000000', NULL, 1),
(3951962, 560464, 57032, '<td valign="top">Good portrayal of emotion. Sharpness is good.</td>', 'Good portrayal of emotion. Sharpness is good.', '2007-07-31 00:46:00.000000', NULL, 1),
(3951966, 560422, 57032, '<td valign="top">Good lighting and contrast. A lot seems lost with all the black, but the hands do a good job of portraying emotion. Good shot.</td>', 'Good lighting and contrast. A lot seems lost with all the black, but the hands do a good job of portraying emotion. Good shot.', '2007-07-31 00:46:55.000000', NULL, 1),
(3951968, 559003, 57032, '<td valign="top">Excellent timing and good contrast.</td>', 'Excellent timing and good contrast.', '2007-07-31 00:47:30.000000', NULL, 1),
