(3951977, 558275, 77397, '<td valign="top">I like the picture a lot. I wonder if it would have been better with the entire tree, or if that would distract. nice job.</td>', 'I like the picture a lot. I wonder if it would have been better with the entire tree, or if that would distract. nice job.', '2007-07-31 00:48:40.000000', NULL, 1),
(3951981, 559139, 57032, '<td valign="top">Good composition. Seems to rely on the title to create an emotion for the dog, rather than letting the dog convey its own emotion.</td>', 'Good composition. Seems to rely on the title to create an emotion for the dog, rather than letting the dog convey its own emotion.', '2007-07-31 00:51:05.000000', NULL, 1),
(3951985, 558302, 57032, '<td valign="top">Blown out highlights on the right are distracting. The colour doesn''t add too much to the photo, so it might have looked better as a duotone or B&amp;W.</td>', 'Blown out highlights on the right are distracting. The colour doesn''t add too much to the photo, so it might have looked better as a duotone or B&W.', '2007-07-31 00:52:10.000000', NULL, 1),
(3951989, 559748, 57032, '<td valign="top">Good composition, but it seems overly staged. The people contrast well against the sand and sky.</td>', 'Good composition, but it seems overly staged. The people contrast well against the sand and sky.', '2007-07-31 00:52:56.000000', NULL, 1),
(3951993, 559399, 57032, '<td valign="top">The skin looks fake; it doesn''t look like a person who''s bleeding. Good timing of the drop.</td>', 'The skin looks fake; it doesn''t look like a person who''s bleeding. Good timing of the drop.', '2007-07-31 00:54:37.000000', NULL, 1),
(3951997, 559879, 57032, '<td valign="top">There isn''t really an aspect that connects me to the emotion here. The blood looks fake, and it''s impossible to tell who got stabbed here.</td>', 'There isn''t really an aspect that connects me to the emotion here. The blood looks fake, and it''s impossible to tell who got stabbed here.', '2007-07-31 00:57:14.000000', NULL, 1),
(3951998, 559411, 77397, '<td valign="top">I actually am crying over this one, and I don''t know why. The title, the shot- It''s overwhelming. Great job. Is it staged or factual? Just curious-<br/>9</td>', 'I actually am crying over this one, and I don''t know why. The title, the shot- It''s overwhelming. Great job. Is it staged or factual? Just curious-9', '2007-07-31 00:57:27.000000', NULL, 1),
(3952001, 560309, 57032, '<td valign="top">Nice timing. The smoke doesn''t detract too much, but a lot of it could have been removed easily. Emotion is conveyed fairly well.</td>', 'Nice timing. The smoke doesn''t detract too much, but a lot of it could have been removed easily. Emotion is conveyed fairly well.', '2007-07-31 00:58:56.000000', NULL, 1),
(3952006, 559797, 57032, '<td valign="top">Definitely an emotional shot, with good focus at the end of the gun.</td>', 'Definitely an emotional shot, with good focus at the end of the gun.', '2007-07-31 01:00:51.000000', NULL, 1),
(3952008, 558595, 57032, '<td valign="top">Good emotion in the young girls, but a bit grainy and dark.</td>', 'Good emotion in the young girls, but a bit grainy and dark.', '2007-07-31 01:01:39.000000', NULL, 1),
(3952009, 557325, 57032, '<td valign="top">Good colour, but the highlights are extremely blown out.</td>', 'Good colour, but the highlights are extremely blown out.', '2007-07-31 01:01:50.000000', NULL, 1),
