(3952021, 560200, 57032, '<td valign="top">The grain effect is overdone, in my opinion. Good contrast.</td>', 'The grain effect is overdone, in my opinion. Good contrast.', '2007-07-31 01:05:28.000000', NULL, 1),
(3952026, 560293, 57032, '<td valign="top">Well composed, but overly reliant on the title it seems. Good contrast.</td>', 'Well composed, but overly reliant on the title it seems. Good contrast.', '2007-07-31 01:07:56.000000', NULL, 1),
(3952030, 560561, 57032, '<td valign="top">Good portrayal of emotion.</td>', 'Good portrayal of emotion.', '2007-07-31 01:09:09.000000', NULL, 1),
(3952032, 559361, 57032, '<td valign="top">A bit blown out in the hand.</td>', 'A bit blown out in the hand.', '2007-07-31 01:09:44.000000', NULL, 1),
